#!/bin/sh
# A2 candidates (style v3): the act 2 and 3 cast, 8 seeds each. Every content.md part must be visible.
set -e
G="python art/gen.py --kind character"
N="human, person, frame, border, vintage print, photograph, figurine base"
$G --asset steam-wraith --view profile --extra-negative "$N, ghost sheet, horror" --subject "side view profile of one Steam Wraith facing left, a wispy body of white steam held in a riveted copper frame skeleton, one long hollow brass claw reaching forward, a round vent grille in its chest breathing cold mist, glowing teal eyes, floating low"
$G --asset valve-crab --view profile --extra-negative "$N, real crab" --subject "side view profile of one Valve Crab facing left, a brass mechanical crab with one huge pincer raised, a big brass valve wheel on its back, riveted teal shell, six jointed legs held apart, glowing eye stalks"
$G --asset furnace-golem --view front --extra-negative "$N" --subject "one Furnace Golem standing alone, front view, a squat iron furnace body with a glowing open furnace door in its chest, one huge fist of black slag and molten cracks, the other arm smaller, short heavy legs, chimney on its head venting smoke, arms clear of the body"
$G --asset pipe-snake --view profile --extra-negative "$N, real snake" --subject "side view profile of one Pipe Snake facing left, a long snake made of jointed brass and copper pipes, a forked valve head with fangs and glowing eyes raised to strike, its tail coiled into a tight pipe spiral, rivets and gauges along its body"
$G --asset gauge-gremlin --view profile --extra-negative "$N" --subject "side view profile of one small Gauge Gremlin facing left, an impish clockwork gremlin with a pressure gauge for a face, big ears, holding an oversized wrench in one hand and a spanner in the other, skinny limbs held apart, mischievous grin"
$G --asset pressure-warden --view front --extra-negative "$N" --subject "one Pressure Warden standing alone, front view, a tall armored boiler automaton elite, a glass pressure dome on its head with steam swirling inside, one massive piston fist, a big intake valve wheel on its side, riveted brass and teal plates, arms clear of the body, symmetrical"
$G --asset twin-pistons --view front --extra-negative "$N" --subject "one Piston twin standing alone, front view, a tall narrow automaton built around one huge vertical piston rod as a ram arm, a domed cylinder cap shield on its other arm, a short crossbar stub at its shoulder, riveted iron and brass, arms clear of the body"
$G --asset bell-ringer --view front --extra-negative "$N" --subject "one Bell Ringer standing alone, front view, a hunched bronze bell automaton, its body a great cracked church bell with an iron clapper hanging inside, one heavy fist, a thick bell rope slung over its shoulder, small glowing eyes under the bell rim, arms clear of the body"
$G --asset chime-moth --view profile --extra-negative "$N, real moth" --subject "side view profile of one Chime Moth facing left, a clockwork moth with wings made of thin brass chime plates and tubular bells, a fuzzy back covered in glittering dust, feathery antennae, glowing amber eyes, wings spread apart"
$G --asset hour-knight --view front --extra-negative "$N" --subject "one Hour Hand Knight standing alone, front view, a tall armored clockwork knight, a sword shaped like a giant clock hour hand, a round shield that is a clock dial, a visored helm with a glowing slit, brass and teal armor, arms clear of the body"
$G --asset echo-sprite --view profile --extra-negative "$N" --subject "side view profile of one Echo Sprite facing left, a small floating clockwork spirit like a tuning fork creature, a wide open round mouth like a horn, one mirror-bright fin on its back, glowing eyes, faint sound rings"
$G --asset pendulum-blade --view front --extra-negative "$N" --subject "one Pendulum Blade standing alone, front view, a tall clock tower mechanism automaton with a huge curved pendulum blade swinging below it, a heavy brass counterweight at its base, gears visible inside its frame, menacing"
$G --asset minute-warden --view front --extra-negative "$N" --subject "one Minute Warden standing alone, front view, a tall gaunt clockwork guardian elite, a toothed mender wheel spinning in its chest, a long minute hand as a weapon, a sharp needle at its wrist, a clock face set in its belly, brass and verdigris, arms clear of the body"
$G --asset orrery --view front --extra-negative "$N" --subject "one Grand Orrery standing alone, front view, a huge clockwork orrery machine elite, a glowing core inside a great brass ring, a long brass orbit arm, three small moons on rods around it: a pale moon, a red ember moon and a dark slow moon, on a short tripod base"
$G --asset clockmaker --view front --extra-negative "$N, old man face, beard, skull" --subject "full body front view of the Clockmaker, the final boss, a tall elegant clockwork automaton in a long brass and teal coat, a porcelain clock face for a head with glowing eyes, an hour hand strapped across his chest, a mainspring coiled at his side, a great gear wheel behind his head like a halo, a small bell in his chest, arms held clear of the body, symmetrical, regal and sad"
